export type RankedCourse = { course: Course; score: number; reasons: string[]; missing: string[]; };
export function rankCourses(profile: Profile): RankedCourse[] {
  return courses.filter(c => !profile.completed.includes(c.id)).map(course => {
    const shared = course.tags.filter(tag => profile.interests.includes(tag));
    const missing = course.prerequisiteIds.filter(id => !profile.completed.includes(id));
    const reasons: string[] = [];
    let score = shared.length * 30;
    if (shared.length) reasons.push(`Matches your interest in ${shared[0].toLowerCase()}`);
    if (profile.assessment !== "No preference" && course.format === profile.assessment) { score += 18; reasons.push(`${course.format === "Projects" ? "Project-focused" : "Exam-focused"} assessment preference`); }
    if (course.hours <= profile.workload) { score += 12; reasons.push("Within your weekly workload preference"); } else score -= (course.hours-profile.workload)*3;
    score -= missing.length*12;
    return {course,score,reasons:reasons.length ? reasons : ["An option to explore beyond your current interests"],missing};
  }).sort((a,b) => b.score-a.score || a.course.title.localeCompare(b.course.title));
}
